-- Notification service schema. Port of the reference's alembic 001_initial_schema
-- (alerts, notifications, alert_configs) plus what the Spring port adds:
--   * alerts.subject_key           what the per-rule cooldown is keyed on
--   * notifications.status         also 'skipped' (a channel that is not configured is
--                                  recorded as skipped, never silently as 'sent')
--   * detector_state / processed_audit_events   the detector watermark
--   * shedlock                     the scheduler lock (one detector run cluster-wide)
-- UUIDs are generated by the application (gen_random_uuid() is kept as a default for
-- manual inserts; it is built in from PostgreSQL 13, so no pgcrypto extension needed).

CREATE TABLE alerts (
    id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    rule_name        TEXT        NOT NULL,
    severity         TEXT        NOT NULL,
    user_id          TEXT,
    ip_address       TEXT,
    app_id           TEXT,
    subject_key      TEXT        NOT NULL DEFAULT 'none',
    details          JSONB       NOT NULL DEFAULT '{}'::jsonb,
    acknowledged     BOOLEAN     NOT NULL DEFAULT FALSE,
    acknowledged_by  TEXT,
    acknowledged_at  TIMESTAMPTZ,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT ck_alerts_severity CHECK (severity IN ('CRITICAL', 'WARNING', 'INFO'))
);

CREATE INDEX idx_alerts_rule_name  ON alerts (rule_name);
CREATE INDEX idx_alerts_severity   ON alerts (severity);
CREATE INDEX idx_alerts_user_id    ON alerts (user_id);
CREATE INDEX idx_alerts_created_at ON alerts (created_at DESC);
CREATE INDEX idx_alerts_ack        ON alerts (acknowledged);
CREATE INDEX idx_alerts_cooldown   ON alerts (rule_name, subject_key, created_at DESC) WHERE NOT acknowledged;

CREATE TABLE notifications (
    id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    alert_id    UUID        NOT NULL REFERENCES alerts (id) ON DELETE CASCADE,
    channel     TEXT        NOT NULL,
    recipient   TEXT        NOT NULL,
    title       TEXT        NOT NULL,
    message     TEXT        NOT NULL DEFAULT '',
    is_read     BOOLEAN     NOT NULL DEFAULT FALSE,
    status      TEXT        NOT NULL DEFAULT 'pending',
    error       TEXT,
    sent_at     TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT ck_notifications_channel CHECK (channel IN ('email', 'inapp', 'webhook')),
    CONSTRAINT ck_notifications_status  CHECK (status IN ('pending', 'sent', 'failed', 'skipped'))
);

CREATE INDEX idx_notifications_alert_id   ON notifications (alert_id);
CREATE INDEX idx_notifications_recipient  ON notifications (recipient);
CREATE INDEX idx_notifications_is_read    ON notifications (is_read);
CREATE INDEX idx_notifications_created_at ON notifications (created_at DESC);

-- Rule configuration overrides (merged over the built-in defaults).
CREATE TABLE alert_configs (
    id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    rule_name        TEXT        NOT NULL UNIQUE,
    enabled          BOOLEAN     NOT NULL DEFAULT TRUE,
    threshold        INTEGER,
    window_minutes   INTEGER,
    severity         TEXT,
    channels         JSONB,
    cooldown_minutes INTEGER,
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Detector watermark: the upper bound (to_date) of the last audit window processed.
CREATE TABLE detector_state (
    name          TEXT        PRIMARY KEY,
    watermark     TIMESTAMPTZ NOT NULL,
    last_run_at   TIMESTAMPTZ NOT NULL,
    last_event_count INTEGER  NOT NULL DEFAULT 0,
    last_alert_count INTEGER  NOT NULL DEFAULT 0
);

-- Audit event ids the detector has already treated as "new" (pruned after a day).
-- Guards the overlap between consecutive fetch windows against double-processing.
CREATE TABLE processed_audit_events (
    event_id      TEXT        PRIMARY KEY,
    created_at    TIMESTAMPTZ NOT NULL,
    processed_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_processed_audit_events_created_at ON processed_audit_events (created_at);

-- ShedLock (JdbcTemplateLockProvider default layout).
CREATE TABLE shedlock (
    name       VARCHAR(64)  NOT NULL PRIMARY KEY,
    lock_until TIMESTAMPTZ  NOT NULL,
    locked_at  TIMESTAMPTZ  NOT NULL,
    locked_by  VARCHAR(255) NOT NULL
);
